// Case 1: User-declared copy op suppresses moves
class LegacyResource {
public:
  LegacyResource(const LegacyResource&); // User-declared copy ctor
  // Compiler will NOT generate move ctor or move assignment op
};

// Case 2: User-declared move op deletes copies
class ModernResource {
public:
  ModernResource(ModernResource&&) noexcept; // User-declared move ctor
  // Compiler DELETES the copy ctor and copy assignment op
};

void example() {
  LegacyResource lr1;
  // LegacyResource lr2 = std::move(lr1); // Error (or copies): no move ctor

  ModernResource mr1;
  // ModernResource mr2(mr1); // Error: copy ctor is deleted
}
